<template>
    <section>
        <div class="my-popups">
        <loader :is-visible="isLoading"></loader>
        <div class="modal d-block">
            <div class="modal-dialog modal-dialog-centered">
                <div class="modal-content">
                    <div class="modal-header theme-primary partition-full">
                        <h4 class="modal-title">Tickets for : {{ assetProductName }}</h4>
                        <button type="button" class="close" v-on:click="Close()">
                            <em class="fa fa-times" aria-hidden="true"></em>
                        </button>
                    </div>

                    <div class="modal-body">
                        <tg-list ModuleName="Ticketing" SubModuleCode="Ticketing" IdentityColumn="TICKET_ID" :listType="['List']"
                            :ListData="GetTicketListing" :HeaderData="Headers" :TotalRecords="TotalRecords" :IsShowAction="true"
                            :RenderRowActionMethod="ticketRenderActions" :ListDataCallBackFunction="FetchRecords"
                            :NorecordfoundText="$t('NoRecordfound')" v-on:ActionButtonClick="ticketActionButtonClick"
                            v-on:PagerButtonClick="pagerMethod" v-on:SortdataButtonClick="sortdata">
                            <template v-slot:slotdata="{ data }">
                                <template v-if="data.column.COLUMN_NAME == 'created_at'">
                                    <span>
                                        {{ $options.filters.formatDate(data.row.created_at) }}
                                    </span>
                                </template>
                                <template v-if="data.column.COLUMN_NAME == 'status_name'">
                                    <a class="inactive-disabled">
                                        <span v-bind:class="getStatusClassList(data.row.status_name, 'status_name')">
                                            {{ data.row[data.column.COLUMN_NAME] }}
                                        </span>
                                    </a>
                                </template>
                          </template>
                        </tg-list>
                    </div>
                </div>
            </div>
        </div>
    </div>
        
    </section>
</template>
<script>

import DataServices from '../../service/DataService'

export default {
    props: {
        assetRelatedInfoId: {
            type: Number,
            required: true
        },
        assetProductName : {
            type: String,
            required: true
        }   
    },
    data() {
        return {
            isLoading:false,
            noRecords: false,
            TotalRecords: 0,
            CurrentPage: 1,
            TotalPages: 0,
            listActions:
                [
                    {
                        title: 'View Ticket Detail',
                        href: 'javascript:void(0)',
                        callbackfunction: 'ClickOnDetail',
                        icon: 'fa fa-eye',
                        additionalSpan: ''
                    }
                ],

            Headers: [{
                "COLUMN_NAME": "ticket_number",
                "DATA_TYPE": "string",
                "SORTABLE": true,
                "VISIBLE": true,
                "DISPLAY_NAME": "Ticket #",
                "DISPLAY_ORDER": 1
            },
            {
                "COLUMN_NAME": "created_at",
                "DATA_TYPE": "string",
                "SORTABLE": false,
                "VISIBLE": true,
                "DISPLAY_NAME": "Created Date",
                "DISPLAY_ORDER": 2,
                settings: {
                    isInSlot: true
                }
            },
            {
                "COLUMN_NAME": "status_name",
                "DATA_TYPE": "string",
                "SORTABLE": false,
                "VISIBLE": true,
                "DISPLAY_NAME": "Status",
                "DISPLAY_ORDER": 3,
                settings: {
                    isInSlot: true
                }
            }
            ],
            SortBy: '',
            SortExp: '',
            PageSize: "10",
            PageNumber: "1",
            GroupStart: 1,
            workOrderId: 0,
            GroupEnd: 3,
            GetTicketListing: []
                 
        }
    },
    created: async function () {
        var vm = this;
        //debugger;;
        setTimeout(() => {
            vm.FetchRecords();
        }, 500);   
    },
    methods: {
        FetchRecords: async function () {
            //debugger;;
            var vueObj = this;
            vueObj.isLoading=true;
          
            var url = `assetRelatedInfoId=${vueObj.assetRelatedInfoId}&sortBy=${vueObj.SortBy}&sortExp=${vueObj.SortExp}&pageSize=${vueObj.PageSize}&pageNumber=${vueObj.PageNumber}&lang=EN`;
            await DataServices.GetTicketListForAsset(url).then(function (response) {
                if (response.data != "" && response.data != null) {
                    if (response.data.result.DATA.length > 0) {
                        vueObj.GetTicketListing = response.data.result.DATA;
                        vueObj.TotalRecords = response.data.result.DATA[0].TOTALRECORDS;
                        vueObj.TotalPages = Math.ceil(vueObj.TotalRecords / vueObj.PageSize);
                        vueObj.CurrentPage = vueObj.PageNumber;
                        vueObj.noRecord = false;
                        vueObj.IsLoad = true;
                    } else {
                        vueObj.noRecord = true;
                        vueObj.TotalRecords = 0
                        vueObj.GetTicketListing = [];
                    }
                    vueObj.isLoading=false;
                }
                else {
                    vueObj.noRecord = true;
                    vueObj.TotalRecords = 0
                    vueObj.GetTicketListing = [];
                }   
                vueObj.isLoading=false;            
            })
        },
        pagerMethod: function (value) {
            this.PageSize = value.PageSize;
            this.PageNumber = value.PageNumber;
            this.FetchRecords();
        },
        sortdata: function (sortBy) {
            this.SortBy = sortBy;
            var sortExp = 'ASC';
            if (this.SortExp == 'ASC') {
                sortExp = 'DESC';
            }
            this.SortExp = sortExp;
            this.SortBy = sortBy;
            this.SortExp = sortExp;
            this.PageNumber = 1;
            this.GroupStart = this.PageNumber;
            this.GroupEnd = this.PageNumber + 2;
            this.FetchRecords();
        },
        ticketActionButtonClick(callbackfunction, item, index, event) {
            ////debugger;;
            switch (callbackfunction) {
                case 'ClickOnDetail':
                    this.DetailLink(item);
                    break;
            }
        },
        DetailLink: function (item) {
            var vm = this;
            window.location.href = "/Ticketing/Manage/"+ encodeURIComponent(item.str_ticket_id);
            // vm.$router.push({ path: "/Ticketing/Manage/" + item.str_ticket_id + "" });
        },
        Close: function () {
            this.$parent.isShowTicket= false;
        },
        ticketRenderActions: function (row) {
            //////debugger;;
            var self = this;
            let rtnActionArray = [];
            self.listActions.forEach(actionItem => {
                let action = { ...actionItem };
                switch (action.title) {
                    case 'Details':
                        action.isVisible = true;
                        break;
                    default: {
                        action.isVisible = true;
                    }
                }
                rtnActionArray.push(action);
            });
            return rtnActionArray;
        },
        getStatusClassList: function (status) {
            var returnClass = '';
            switch (status) {
                case 'UnPublish':
                    returnClass = 'px-2 text-center bg-danger text-white d-block';
                    break;
                case 'Active':
                    returnClass = 'px-2 text-center bg-success text-white d-block';
                    break;
                case 'Reopen':
                    returnClass = 'px-2 bg-primary text-center text-white d-block';
                    break;
                case 'On Hold':
                    returnClass = 'px-2 bg-warning text-center text-white d-block';
                    break;
                case 'Draft':
                    returnClass = 'px-2 text-center bg-warning text-white d-block';
                    break;
                case 'Inactive':
                    returnClass = 'px-2 text-center bg-danger text-white d-block';
                    break;
                case 'Open':
                    returnClass = 'px-2 text-center bg-success text-white d-block';
                    break;
                case 'Waiting':
                    returnClass = 'px-2 text-center bg-warning text-white d-block';
                    break;
                case 'In Progress':
                    returnClass = 'px-2 bg-info text-center text-white d-block';
                    break;
                case 'Completed':
                    returnClass = 'px-2 bg-secondary text-center text-white d-block';
                    break;
                case 'Cancelled':
                    returnClass = 'px-2 bg-danger text-center text-white d-block';
                    break;
                case 'Closed':
                    returnClass = 'px-2 bg-danger text-center text-white d-block';
                    break;
                case 'Closed and Locked':
                    returnClass = 'px-2 bg-danger text-center text-white d-block';
                    break;
                case 'Waiting Resolved': case 'Resolved - Waiting for Client':
                    returnClass = 'px-2 bg-secondary text-center text-white d-block';
                    break;
                case 'Waiting Response': case 'Waiting for Client Response':
                    returnClass = 'px-2 bg-secondary text-center text-white d-block';
                    break;
                default:
                    returnClass = '';
            }
            return returnClass;
        }

    },
}
</script>