<template>
    <div>
        <div ref="calendar"></div>

        <!-- <ViewReservationDetails v-if="showReservationDetails"></ViewReservationDetails> -->
    </div>
</template>

<script>
import { Calendar } from '@fullcalendar/vue';
import dayGridPlugin from '@fullcalendar/daygrid';
import DataService from '../../service/DataService';
// import ViewReservationDetails from './ViewReservationDetails.vue';



export default {
    name: 'Calendar',
    components: {
        Calendar,
        // ViewReservationDetails
    },
    props: {
        eventData: {
            type: Array,
            default: () => []
        },
        ProductId: {
            type: Number,
            required: false
        },
        LocationId: {
            type: Number,
            required: false
        },
        RelatedInfoId: {
            type: Number,
            required: false
        }
    },
    data() {
        return {
            calendar: null,
            initialized: false,
            events: [] // Define events array in data
            , showReservationDetails: false
        };
    },
    mounted() {
        this.renderCalendar();
    },
    methods: {
        renderCalendar() {
            const calendarEl = this.$refs.calendar;
            this.calendar = new Calendar(calendarEl, {
                plugins: [dayGridPlugin],
                initialView: 'dayGridMonth',
                events: this.eventData,
                headerToolbar: {
                    left: 'prev,next today',
                    center: 'title',
                    right: ''
                },
                datesSet: this.handleDatesSet,
                eventClick: this.handleEventClick,
                eventClassNames: this.getEventClassNames,
                eventTimeFormat: false, // Disable time display
                eventContent: function (info) {
                    // Only show the title and hide the time
                    return { html: `<span>${info.event.title}</span>` }; // Render only the event title
                }
            });
            this.calendar.render();
        },

        handleEventClick(info) {
            const event = info.event;
            const title = event.title;
            const start = event.start;
            const end = event.end
            const reversedUser = event.id
            console.log('Event clicked: ', title, start, end, reversedUser);

            this.$emit('RecieveReservationDetails', {
                title,
                start,
                end,
                reversedUser
            });


            info.jsEvent.preventDefault();
        },
        handleDatesSet(info) {
            //var vm = this;
            var productId = this.ProductId ? this.ProductId : 0;
            let url;
            if (this.initialized) {
                var startDt = this.$options.filters.formatDate(info.startStr);
                var endDt = this.$options.filters.formatDate(info.endStr);
                url = `userId=0&locationId=${this.LocationId}&assetCatId=${productId}&rid=${this.RelatedInfoId}&start=${startDt}&end=${endDt}&requestedEventType=`;
                this.LoadAssetCalendar(url);
            } else {
                this.initialized = true;
                url = `userId=0&locationId=${this.LocationId}&assetCatId=${productId}&rid=${this.RelatedInfoId}&start=&end=&requestedEventType=`;
                this.LoadAssetCalendar(url);
            }
        },
        LoadAssetCalendar(url) {
            DataService.LoadAssetCalendar(url).then(response => {
                this.events = [];
                const AssetCalendarData = response.data;
                console.log("AssetCalendarData", this.AssetCalendarData)
                AssetCalendarData.forEach(item => {

                    if (item.title == "RESERVED") {

                        this.events.push({
                            title: item.title + '(' + item.quantity + ')',
                            // start: this.$options.filters.formatDate(item.start),
                            // end: this.$options.filters.formatDate(item.end),
                            start: item.start,
                            end: item.end,
                            // startStr: item.startStr,
                            // endStr: item.endStr,
                            // backgroundColor: '#fdc107',
                            // borderColor: '#fdc107',
                            classNames: this.getEventBackgroudCssClass(item.title),
                            id: item.createD_BY
                        });

                        // let events = [
                        //     {
                        //         title: 'Reserved',
                        //         start: '2025-04-05T11:00:00',
                        //         end: '2025-04-05T12:00:00',
                        //         backgroundColor: '#fdc107',
                        //         borderColor: '#fdc107'
                        //     },
                        //     {
                        //         title: 'Reserved',
                        //         start: '2025-04-06T02:00:00',
                        //         end: '2025-04-06T12:00:00',
                        //         backgroundColor: '#fdc107',
                        //         borderColor: '#fdc107'
                        //     },
                        //     {
                        //         title: 'Reserved',
                        //         start: '2025-04-07T16:00:00',
                        //         end: '2025-04-07T12:00:00',
                        //         backgroundColor: '#fdc107',
                        //         borderColor: '#fdc107'
                        //     },
                        //     {
                        //         title: 'Reserved',
                        //         start: '2025-04-08T19:00:00',
                        //         end: '2025-04-08T12:00:00',
                        //         backgroundColor: '#fdc107',
                        //         borderColor: '#fdc107'
                        //     },
                        //     {
                        //         title: 'Reserved',
                        //         start: '2025-04-09T10:00:00',
                        //         end: '2025-04-09T12:00:00',
                        //         backgroundColor: '#fdc107',
                        //         borderColor: '#fdc107'
                        //     }
                        // ];

                        // this.events = events;
                        // console.log(events);


                    }
                });

                // let obj = {
                //     title: 'Reserved',
                //     start: '2025-04-11',
                //     end: '2025-04-11',
                //     backgroundColor: '#fdc107',
                //     borderColor: '#fdc107'
                // }

                // this.events.push(obj);
                this.calendar.removeAllEvents();
                this.calendar.addEventSource(this.events);
            });
        },
        getEventBackgroudCssClass(title) {

            if (title === 'AVAILABLE') {
                return ['r-calendar-available'];
            } else if (title === 'RESERVED') {
                return ['r-calendar-reserved'];
            } else if (title === 'ASSIGNED') {
                return ['r-calendar-assigned'];
            } else if (title === 'IN-TRANSIT') {
                return ['r-calendar-intransit'];
            } else if (title === 'AUDIT (annual )' || title === 'CALIBRATION (quarterly )') {
                return ['r-calendar-audit'];
            } else {
                return ['r-calendar-light-purple'];
            }
        },
        getEventTextCssClass(title) {

            if (title === 'AVAILABLE') {
                return ['white'];
            } else if (title === 'RESERVED') {
                return ['black'];
            } else if (title === 'ASSIGNED') {
                return ['white'];
            } else if (title === 'IN-TRANSIT') {
                return ['white'];
            } else if (title === 'AUDIT (annual )' || title === 'CALIBRATION (quarterly )') {
                return ['white'];
            } else {
                return ['white'];
            }
        },


    }
};
</script>
<style>
.r-calendar-reserved {
    background-color: #fdc107 !important;
    color: #fff !important;
    padding: 2px !important;
    text-transform: capitalize;
}
</style>